  ('d57a9644-791a-481e-93c1-c89c31944a87', $$Scheikunde$$, $$HAVO$$, $$Toiletpapier wordt bio-ethanol$$, $$HAVO Scheikunde 2024-I$$),
  ('0ddeb54a-e790-489e-8ea0-4b301e27647f', $$Scheikunde$$, $$HAVO$$, $$Koeien boeren methaan op$$, $$HAVO Scheikunde 2024-I$$),
  ('9cbf4823-6350-4757-9ab3-40bf1b094fbe', $$Scheikunde$$, $$HAVO$$, $$Zuurstofvanger$$, $$HAVO Scheikunde 2024-I$$),
  ('052cad00-7101-4786-9c75-0f1176b74706', $$Scheikunde$$, $$HAVO$$, $$Lithium-ion-accu’s recyclen$$, $$HAVO Scheikunde 2024-I$$),
  ('a1ceb518-4f23-4a70-9400-515989abae3b', $$Scheikunde$$, $$HAVO$$, $$Plastic wordt olie$$, $$HAVO Scheikunde 2024-I$$),
  ('4aa1ed9f-a47e-44c6-8835-9bfb3979fc29', $$Scheikunde$$, $$HAVO$$, $$Ademende flowbatterij$$, $$HAVO Scheikunde 2024-I$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('5d65ac84-5c9e-4768-9de9-67bde8f724c3', 'd57a9644-791a-481e-93c1-c89c31944a87', $$tekstfragment — rioolwaterzuivering en cellulosevezels$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-toiletpapier-wordt-bio-ethanol-context1.png$$,
   $$Een rioolwaterzuiveringsinstallatie zuivert rioolwater voordat het in het oppervlaktewater wordt geloosd. Het rioolwater ondergaat daarbij een reinigingsstap om cellulosevezels te verwijderen die afkomstig zijn uit toiletpapier. Cellulosevezels lossen namelijk slecht op in water en zijn lastig afbreekbaar. Bovendien kunnen deze vezels nuttig worden gebruikt als grondstof voor de brandstof bio-ethanol.$$, 'inline'),
  ('6b613c66-6bc1-412d-a6f3-6cb4f0c7b349', 'd57a9644-791a-481e-93c1-c89c31944a87', $$tekstfragment — waterstofbruggen tussen cellulosemoleculen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-toiletpapier-wordt-bio-ethanol-context2.png$$,
   $$De slechte oplosbaarheid van cellulosevezels in water wordt onder meer veroorzaakt doordat cellulosemoleculen onderling stevig zijn gebonden door middel van waterstofbruggen. Op de uitwerkbijlage zijn fragmenten van twee cellulosemoleculen in structuurformule weergegeven.$$, 'inline'),
  ('fd2d9ae6-3239-42ba-9c15-940694ca15ef', 'd57a9644-791a-481e-93c1-c89c31944a87', $$uitwerkbijlage vraag 2 — twee cellulosemoleculen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-toiletpapier-wordt-bio-ethanol-context3-uitwerkbijlage.png$$,
   $$uitwerkbijlage bij vraag 2: twee fragmenten van cellulosemoleculen zijn in structuurformule weergegeven (elk fragment bestaat uit drie aan elkaar gekoppelde glucose-eenheden, met CH₂OH-, OH- en O-groepen); de leerling moet twee waterstofbruggen tekenen die de twee cellulosemoleculen met elkaar verbinden, weergegeven met stippellijntjes.$$, 'uitwerkbijlage'),
  ('64532840-a510-401b-a213-b064d1f96f33', 'd57a9644-791a-481e-93c1-c89c31944a87', $$proces A — syngas via stoomverhitting, reactie 1 en 2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-toiletpapier-wordt-bio-ethanol-context4.png$$,
   $$In deze opgave worden twee processen (A en B) vergeleken waarmee cellulose uit toiletpapier kan worden omgezet tot bio-ethanol.
In proces A wordt cellulose met stoom verhit bij een temperatuur van 700 °C. Hierbij ontstaat een mengsel van gassen. Nadat verontreinigingen zijn verwijderd, blijft syngas over. Syngas is een mengsel van waterstof en koolstofmono-oxide. Dit syngas wordt vervolgens door bacteriën in een waterige omgeving via reactie 1 en reactie 2 omgezet.
6 CO + 3 H₂O → C₂H₆O + 4 CO₂ (reactie 1)
2 CO₂ + 6 H₂ → C₂H₆O + 3 H₂O (reactie 2)
Hierbij wordt alle CO₂ die in reactie 1 ontstaat, bij reactie 2 gebruikt. Daardoor komt de totale reactie neer op de omzetting van syngas tot uitsluitend ethanol (C₂H₆O) en water. De vergelijking van de totale reactie kun je opstellen door beide reacties in de juiste verhouding bij elkaar op te tellen.$$, 'inline'),
  ('22d39b29-535c-4602-93c3-170d38f528e2', 'd57a9644-791a-481e-93c1-c89c31944a87', $$proces B — cellotriose en reactie 3$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-toiletpapier-wordt-bio-ethanol-context5.png$$,
   $$Proces B maakt gebruik van een samenwerking tussen een bacterie en een gist. Bij een temperatuur van 30 °C zorgt de bacterie voor de omzetting van cellulose met water tot onder andere het sacharide cellotriose (C₁₈H₃₂O₁₆). De gist zet vervolgens cellotriose om tot ethanol en CO₂ volgens reactie 3.
C₁₈H₃₂O₁₆ + 2 H₂O → 6 C₂H₆O + 6 CO₂ (reactie 3)
De productie van ethanol volgens reactie 3 heeft een lage atoomeconomie.$$, 'inline'),
  ('493fd42c-3cc9-4e2f-8801-9ccebc445aa1', 'd57a9644-791a-481e-93c1-c89c31944a87', $$vergelijking proces A en proces B — groene chemie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-toiletpapier-wordt-bio-ethanol-context6.png$$,
   $$Proces A en proces B kunnen met elkaar worden vergeleken volgens de uitgangspunten van de groene chemie. Een nadeel van proces B is de lage atoomeconomie van de productie van ethanol in reactie 3. Toch zijn er ook uitgangspunten die in het voordeel van proces B uitvallen.$$, 'inline'),
  ('3d08ba4e-1571-4c33-9283-a4781be9b597', '0ddeb54a-e790-489e-8ea0-4b301e27647f', $$tekstfragment — methaanuitstoot door koeien$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-koeien-boeren-methaan-op-context1.png$$,
   $$Koeien stoten gemiddeld 13 gram methaan per liter melk uit. Deze uitstoot heeft een even groot ongewenst effect op het klimaat als 1,24 kilogram koolstofdioxide.$$, 'inline'),
  ('56f30129-eebc-4dfc-b2d1-f83a97e63f43', '0ddeb54a-e790-489e-8ea0-4b301e27647f', $$vertering van gras — hydrolyse van cellulose in de pens$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-koeien-boeren-methaan-op-context2.png$$,
   $$Methaan ontstaat door reacties die plaatsvinden tijdens de spijsvertering bij de koe. Als een koe gras eet, komt dit gras terecht in de maag die de pens wordt genoemd. Gras bevat cellulose. In de pens van een koe leven verschillende soorten micro-organismen die cellulose door hydrolyse afbreken tot onder meer monosachariden en disachariden. Op de uitwerkbijlage is de vergelijking van de hydrolyse van het uiteinde van een cellulosemolecuul onvolledig weergegeven.$$, 'inline'),
  ('9cacc8df-6a8f-431e-8f20-140b96c0fbc2', '0ddeb54a-e790-489e-8ea0-4b301e27647f', $$uitwerkbijlage vraag 7 — onvolledige hydrolysevergelijking cellulose$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-koeien-boeren-methaan-op-context3-uitwerkbijlage.png$$,
   $$onvolledige reactievergelijking op de uitwerkbijlage: een fragment van een cellulosemolecuul (drie aan elkaar gekoppelde glucose-eenheden, in structuurformule) reageert met een onbenoemde stof (+ …) tot twee producten; de leerling moet de hydrolyse compleet maken zodat één disacharidemolecuul wordt afgesplitst, met structuurformules op de stippellijntjes.$$, 'uitwerkbijlage'),
  ('4f748744-fe64-4b71-bad1-7bc8c930a086', '0ddeb54a-e790-489e-8ea0-4b301e27647f', $$afbraak van glucose door micro-organismen in de pens$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-koeien-boeren-methaan-op-context4.png$$,
   $$Een aantal soorten micro-organismen die in de pens leven, voorzien in hun energiebehoefte door de afbraak van de monosacharide glucose. Een voorbeeld hiervan is de reactie waarbij glucose en water worden omgezet tot azijnzuur, koolstofdioxide en waterstof.$$, 'inline'),
  ('842b19cd-32cf-47bc-be6b-40890406dd9a', '0ddeb54a-e790-489e-8ea0-4b301e27647f', $$vorming van methaan uit waterstof — reactie 1$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-koeien-boeren-methaan-op-context5.png$$,
   $$De waterstof die in de pens ontstaat, wordt met behulp van het enzym MCR, dat in bepaalde micro-organismen voorkomt, vrijwel meteen omgezet tot methaan. Hierbij treedt reactie 1 op.
4 H₂ (g) + CO₂ (g) → CH₄ (g) + 2 H₂O (l) (reactie 1)
Methaan neemt in de pens van de koe een groot volume in.$$, 'inline'),
  ('ffe204aa-e978-4e62-a130-dd1f9c20fd8d', '0ddeb54a-e790-489e-8ea0-4b301e27647f', $$3-NOP remt het enzym MCR$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-koeien-boeren-methaan-op-context6.png$$,
   $$Koeien boeren methaan op of laten scheten van methaan, waardoor methaan in de lucht terechtkomt. Men kan de hoeveelheid methaan die een koe met boeren uitstoot, laten afnemen door aan het voer een kleine hoeveelheid van de stof 3-NOP toe te voegen.
Door de aanwezigheid van 3-NOP wordt het enzym MCR minder werkzaam.$$, 'inline'),
  ('4e4355c6-bd7b-407e-b8fd-a86db3fbbc48', '0ddeb54a-e790-489e-8ea0-4b301e27647f', $$3-NOP wordt omgezet tot propaan-1,3-diol$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-koeien-boeren-methaan-op-context7.png$$,
   $$In een onderzoek werd aangetoond dat 3-NOP in pensvloeistof (maagsap) langzaam maar volledig wordt omgezet tot het onschadelijke propaan-1,3-diol.$$, 'inline'),
  ('3c73c372-8d45-4356-a454-f229bfc6a1ec', '9cbf4823-6350-4757-9ab3-40bf1b094fbe', $$figuur 1 — opbouw van OxyGuard verpakkingsmateriaal$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-zuurstofvanger-context1.png$$,
   $$Om voorverpakt voedsel lange tijd te kunnen bewaren, is het belangrijk dat er zo weinig mogelijk zuurstof in de verpakking aanwezig is. Daarom is OxyGuard™ ontwikkeld: een verpakkingsmateriaal dat in staat is om zuurstof in de verpakking ‘weg te vangen’ en zuurstof buiten de verpakking erbuiten te houden. OxyGuard™ is opgebouwd uit verschillende lagen poly-etheen (PE), een laag aluminium en een laag poly-ethyleentereftalaat (PET). In figuur 1 is deze opbouw vereenvoudigd weergegeven.
figuur 1: doorsnede van het verpakkingsmateriaal met van binnen naar buiten de lagen A (PE met silica), B (PE met onder andere ijzerdeeltjes), C (PE), D (aluminium) en E (PET); zuurstof (O₂) diffundeert vanuit de binnenzijde van de verpakking door laag A en wordt weggevangen in laag B, terwijl zuurstof van de buitenzijde niet naar binnen kan doordringen.$$, 'inline'),
  ('fc94c9cd-debf-4ab8-8774-d8091d253bd5', '9cbf4823-6350-4757-9ab3-40bf1b094fbe', $$figuur 2 — extruderen van de PE-lagen tot folie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-zuurstofvanger-context2.png$$,
   $$Laag A, B en C (figuur 1) zijn gemaakt van PE. Deze lagen van PE worden gemaakt door extruderen met drie extruders. Hierna volgt een proces waarbij de gesmolten lagen door een verdeelstuk gaan en er een folie ontstaat die uit drie lagen bestaat. Figuur 2 toont deze processen en de structuurformule van PE.
figuur 2: drie extruders (voor laag A, B en C) voeren via een toevoerbuis gesmolten PE naar een verdeelstuk, waarna het mengsel via een koelrol wordt afgekoeld tot een folie; rechts de structuurformule van PE: -(-CH₂-CH₂-)n-.$$, 'inline'),
  ('cb5f3a16-189f-44ae-9500-4970bbbe972d', '9cbf4823-6350-4757-9ab3-40bf1b094fbe', $$reactie 1 — wegvangen van zuurstof door ijzerdeeltjes$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-zuurstofvanger-context3.png$$,
   $$Laag B bevat behalve PE onder andere ijzerdeeltjes, waardoor deze laag de zuurstof die in de verpakking zit, kan ‘wegvangen’ volgens reactie 1.
3 O₂ (g) + 4 Fe (s) → 2 Fe₂O₃ (s) (reactie 1)
Deze reactie verloopt bij lage vochtigheid zeer langzaam. Daarom bevat laag A silica (SiO₂). Silica is nodig om water aan laag A te laten binden om zo reactie 1 in laag B te versnellen. PE zelf kan namelijk geen water binden.$$, 'inline'),
  ('8dd98e74-d2e9-4695-b706-2badecaccfed', '9cbf4823-6350-4757-9ab3-40bf1b094fbe', $$figuur 3 — weggevangen zuurstof versus gebonden water, en afmetingen zakje$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-zuurstofvanger-context4.png$$,
   $$De hoeveelheid water die per m² verpakkingsmateriaal gebonden is, heeft invloed op de hoeveelheid zuurstof die weggevangen kan worden. In figuur 3 staat dit verband in een diagram weergegeven.
figuur 3: grafiek met op de x-as de hoeveelheid gebonden water (0-2,0 g m⁻², met een onderbreking tussen 0 en ongeveer 0,9) en op de y-as de hoeveelheid weggevangen O₂ (0,015-0,030 cm³ cm⁻², met een onderbreking onderin); de meetpunten liggen op een rechte lijn die stijgt van ongeveer (1,0; 0,018) tot ongeveer (1,7; 0,028).
Onderzoekers maakten een rechthoekig zakje uit 2 stukjes van 6,5 bij 7,75 cm van het verpakkingsmateriaal OxyguardTM. Nadat het zakje was gevuld met een droog voedingsmiddel en was afgesloten, bevond zich nog 13,4 cm³ lucht in het zakje. De lucht bevatte 20,9 volumeprocent zuurstof.$$, 'inline'),
  ('c98708f6-b01d-48a5-9363-c67e9debd4a8', '9cbf4823-6350-4757-9ab3-40bf1b094fbe', $$laag D en E — aluminium en PET ter verstijving$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-zuurstofvanger-context5.png$$,
   $$Laag D en E van OxyGuard™ dienen ter versteviging. Laag D, gemaakt van aluminium, laat geen zuurstof van buitenaf door. Laag E bestaat uit het ketenpolymeer PET. De ketens van PET zijn hydrofoob. PET en aluminium zijn beide niet poreus. Toch kan PET wel zuurstofmoleculen doorlaten en aluminium (Al) niet.$$, 'inline'),
  ('f0ed21ad-f26b-4cc4-9476-dc34622f98ab', '9cbf4823-6350-4757-9ab3-40bf1b094fbe', $$OxyGuard verpakkingen zijn niet opnieuw te verwerken$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-zuurstofvanger-context6.png$$,
   $$Verpakkingen van OxyGuard™ kunnen na gebruik niet worden verwerkt tot nieuwe verpakkingen van OxyGuard™.$$, 'inline'),
  ('2418a11a-fbfc-4b49-9f84-99309d025ff8', '052cad00-7101-4786-9c75-0f1176b74706', $$tekstfragment — LiPF₆ reageert met water$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-lithium-ion-accus-recyclen-context1.png$$,
   $$In steeds meer elektrische voertuigen zitten lithium-ion-accu’s (LIA’s). Daardoor neemt ook het afval van afgedankte LIA’s toe. Afgedankte LIA’s moeten apart ingezameld worden. De elektrolytvloeistof bevat namelijk de stof LiPF₆, die gemakkelijk reageert met water. Bij deze reactie ontstaan lithiumfluoride en de giftige stoffen waterstoffluoride (HF) en fosforylfluoride (POF₃).$$, 'inline'),
  ('f7ef102d-4c39-4cce-8b91-6b59ee592186', '052cad00-7101-4786-9c75-0f1176b74706', $$figuur 1 — samenstelling van een LIA$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-lithium-ion-accus-recyclen-context2.png$$,
   $$De ingezamelde LIA’s kunnen worden gerecycled, om zo min mogelijk metalen verloren te laten gaan. Figuur 1 toont de samenstelling van een bepaald type LIA met aluminium behuizing.
figuur 1: cirkeldiagram met de samenstelling van de LIA: 33% actieve stof (positieve elektrode), 19% grafiet (negatieve elektrode), 11% koper, 15% elektrolytvloeistof, 4% plastics, 18% aluminium (inclusief behuizing).$$, 'inline'),
  ('c961bff1-e25a-442a-b0ba-7683db811791', '052cad00-7101-4786-9c75-0f1176b74706', $$verhoudingsformule van de actieve stof in de positieve elektrode$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-lithium-ion-accus-recyclen-context3.png$$,
   $$De positieve elektrode van dit type LIA bevat een actieve stof met lithium-ionen, nikkel-ionen, mangaan-ionen en kobalt-ionen. De verhoudingsformule kan als volgt worden genoteerd:
LiNi₀,₈₀Mn₀,₁₀Co₀,₁₀O₂.$$, 'inline'),
  ('a9e2e89c-d9ef-4b1a-b8c9-12d8e64c35c9', '052cad00-7101-4786-9c75-0f1176b74706', $$ontladen van LIA's in zoutoplossing$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-lithium-ion-accus-recyclen-context4.png$$,
   $$Afgedankte LIA’s zijn vaak nog deels opgeladen. Voordat de LIA’s worden gerecycled, worden ze ontladen. Dit kan door ze in een oplossing van natriumchloride in water te leggen. Beide elektroden moeten contact maken met de oplossing.$$, 'inline'),
  ('18b420fe-8ee5-40fb-9a8a-0d853cea1cce', '052cad00-7101-4786-9c75-0f1176b74706', $$figuur 2 — Umicore-oven met drie temperatuurzones$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-lithium-ion-accus-recyclen-context5.png$$,
   $$Het Belgische bedrijf Umicore heeft een proces ontwikkeld om nikkel en kobalt terug te winnen uit LIA’s. Dit proces maakt gebruik van een oven met drie temperatuurzones (vereenvoudigd weergegeven in figuur 2). De LIA’s worden samen met zand, aluminiumoxide en ongebluste kalk van bovenaf in de oven gebracht. In elke zone vindt een ander onderdeel van het recyclingproces plaats. De gassen die in zone 1, 2 en 3 ontstaan, stijgen op en worden verzameld voor verdere reiniging. Gedurende het verblijf in de oven zakken vaste stoffen en vloeistoffen naar beneden en komen ze in een steeds hetere omgeving.
figuur 2: oven met van boven naar beneden zone 1 (T < 300 °C, elektrolyt verdampt), zone 2 (T ≈ 700 °C, plastics ontleden) en zone 3 (T = 1200-1400 °C, behuizing reageert); bovenin gaan de LIA's, zand, aluminiumoxide en ongebluste kalk naar binnen, samen met toevoerlucht met extra O₂; bovenaan verlaten gassen de oven; onderaan worden vaste stoffen en gesmolten metalen afgevoerd.$$, 'inline'),
  ('27e082ea-a8d0-4d8b-bc26-596f160ca04c', '052cad00-7101-4786-9c75-0f1176b74706', $$tekstfragment — tabel over aluminium op de uitwerkbijlage$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-lithium-ion-accus-recyclen-context6.png$$,
   $$Op de uitwerkbijlage staat een tabel over aluminium.$$, 'inline'),
  ('7ac1a41e-142b-4545-93e9-6faaec955610', '052cad00-7101-4786-9c75-0f1176b74706', $$uitwerkbijlage vraag 20 — tabel smelt- en kookpunt aluminium$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-lithium-ion-accus-recyclen-context7-uitwerkbijlage.png$$,
   $$tabel op de uitwerkbijlage met kolommen temperatuur (K), temperatuur (°C) en fase (s, l, g of aq), met rijen ‘smeltpunt aluminium’, ‘kookpunt aluminium’ en ‘de fase in zone 2’; de cellen voor smeltpunt (K en °C), kookpunt (K en °C) en de fase in zone 2 zijn leeg (…) en moeten door de leerling worden ingevuld.$$, 'uitwerkbijlage'),
  ('4d792896-0c04-4bad-a76f-422d73a2f5c7', '052cad00-7101-4786-9c75-0f1176b74706', $$reactie 1 — verbranding van aluminium in zone 3$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-lithium-ion-accus-recyclen-context8.png$$,
   $$De hoge temperatuur in zone 3 wordt bereikt door de exotherme reactie tussen aluminium en zuurstof (reactie 1).
4 Al + 3 O₂ → 2 Al₂O₃ (reactie 1)
Op de uitwerkbijlage is het energiediagram van reactie 1 onvolledig weergegeven. In dit energiediagram ontbreekt het niveau van het reactieproduct.$$, 'inline'),
  ('16277651-e780-4618-9f0c-5f4d4e53d903', '052cad00-7101-4786-9c75-0f1176b74706', $$uitwerkbijlage vraag 21 — onvolledig energiediagram reactie 1$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-lithium-ion-accus-recyclen-context9-uitwerkbijlage.png$$,
   $$onvolledig energiediagram op de uitwerkbijlage: op de energie-as staat alleen het energieniveau van de beginstoffen ‘4 Al + 3 O₂’ getekend, met de aanduiding ‘geactiveerde toestand’ erboven; het energieniveau van het reactieproduct aluminiumoxide ontbreekt en moet door de leerling worden getekend en van een bijschrift worden voorzien, waarna ∆E op de juiste plaats moet worden aangegeven.$$, 'uitwerkbijlage'),
  ('6c18d813-4e23-40de-934c-fb7b4b89a215', '052cad00-7101-4786-9c75-0f1176b74706', $$scheiding van vaste stoffen en legering onderin de oven$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-lithium-ion-accus-recyclen-context10.png$$,
   $$Aan de onderkant van de oven stroomt een mengsel van vaste stoffen (Li₂CO₃ en Al₂O₃) en een vloeibare legering van koper, kobalt en nikkel naar buiten. De vaste stoffen drijven op de vloeibare legering en kunnen gescheiden worden van de legering. Dit kan worden opgevat als bezinken.$$, 'inline'),
  ('53261637-3f77-4d58-98f3-58db2a6e3266', '052cad00-7101-4786-9c75-0f1176b74706', $$extractie — kobalt reageert met zoutzuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-lithium-ion-accus-recyclen-context11.png$$,
   $$De legering van koper, kobalt en nikkel wordt vervolgens na enkele extractie-stappen gebruikt om nieuwe actieve stof voor de positieve elektrode te maken. Een voorbeeld van zo’n stap is een behandeling met zoutzuur. Hierbij reageert zoutzuur met kobalt tot waterstofgas en een oplossing met Co²⁺-ionen en Cl⁻-ionen.$$, 'inline'),
  ('ee2a612e-aefb-4786-a1af-bc88dbc0f339', 'a1ceb518-4f23-4a70-9400-515989abae3b', $$figuur 1 — PP en het batchproces (stap 1 t/m 4)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-plastic-wordt-olie-context1.png$$,
   $$Amerikaanse onderzoekers hebben een nieuwe methode bedacht om moeilijk recyclebaar plasticafval om te zetten tot olie. Voor het testen van hun methode gebruikten de onderzoekers polypropeen (PP, zie figuur 1). De onderzoekers gebruikten een proces waarin bij hoge temperatuur (380-450 °C) en hoge druk steeds 1,0 g van de vaste stof PP in een reactor in contact wordt gebracht met water. Het water reageert hierbij niet. Onder de genoemde omstandigheden in de reactor ontleden PP-moleculen tot kleinere moleculen. Het gebruikte batchproces bestaat uit de volgende stappen:
stap 1: PP en water worden in een reactor gebracht. Door vervolgens de temperatuur en de druk te verhogen ondergaat PP diverse reacties.
stap 2: De reactor wordt afgekoeld en de ontstane gassen worden afgevoerd. In de reactor ontstaat een mengsel van olie, water en een vaste stof. Deze vaste stof bestaat ook uit PP. Maar de gemiddelde molecuulmassa is lager dan het PP dat de reactor ingaat.
stap 3: Het reactormengsel wordt in scheidingsruimte S1 gefiltreerd, waardoor de vaste stof wordt afgescheiden.
stap 4: Het filtraat wordt in scheidingsruimte S2 verder gescheiden.
figuur 1: structuurformule van polypropeen (PP): -(-CH(CH₃)-CH₂-)n-.$$, 'inline'),
  ('3ce24ac1-9dab-4dd4-a080-00854000e335', 'a1ceb518-4f23-4a70-9400-515989abae3b', $$tekstfragment — proces op uitwerkbijlage weergegeven$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-plastic-wordt-olie-context2.png$$,
   $$Op de uitwerkbijlage is dit proces gedeeltelijk weergegeven.$$, 'inline'),
  ('5b57f675-91da-4850-bda1-2cdba88f3e00', 'a1ceb518-4f23-4a70-9400-515989abae3b', $$uitwerkbijlage vraag 24 — onvolledig blokschema batchproces$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-plastic-wordt-olie-context3-uitwerkbijlage.png$$,
   $$onvolledig blokschema op de uitwerkbijlage: de stofstromen PP en ‘…’ (water) gaan via pijlen de ‘reactor’ in; de leerling moet de twee ontbrekende blokken van scheidingsruimten S1 en S2 tekenen, de pijlen van de ontbrekende stofstromen tekenen, en de nummers van de stoffen (1 gassen, 2 olie, 3 vaste stof, 4 water) bij de juiste pijlen noteren, waarbij sommige nummers meer dan één keer gebruikt moeten worden.$$, 'uitwerkbijlage'),
  ('dc4dcdf8-0e66-45e8-9a2d-4269f7f11577', 'a1ceb518-4f23-4a70-9400-515989abae3b', $$tekstfragment — vaste stof (PP) hergebruiken voor olie-opbrengst$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-plastic-wordt-olie-context4.png$$,
   $$De onderzoekers wilden weten of de vaste stof (PP) die S1 verlaat, kan worden gebruikt om de olie-opbrengst te vergroten.$$, 'inline'),
  ('3b4a3f12-bbdf-4fb2-a853-d83692f7bf05', 'a1ceb518-4f23-4a70-9400-515989abae3b', $$figuur 2 — opbrengst olie, gas en vaste stof bij drie temperaturen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-plastic-wordt-olie-context5.png$$,
   $$Om de invloed te onderzoeken van reactietemperatuur en reactietijd op de opbrengst en samenstelling van de reactieproducten, werden verschillende experimenten uitgevoerd bij temperaturen tussen 380 °C en 450 °C en reactietijden tussen 0,5 en 4 uur. Na afloop van elk experiment werd de opbrengst aan vaste stof, olie en gassen bepaald. In figuur 2 zijn de resultaten in drie diagrammen weergegeven.
figuur 2: drie diagrammen (A: T = 380 °C, B: T = 400 °C, C: T = 450 °C) met op de x-as de tijd (0-4 uur) en op de y-as de opbrengst (massa%) van olie, gas en vaste stof (PP en PP-fragmenten). In diagram A daalt de vaste stof geleidelijk van 100% naar ongeveer 83% terwijl olie langzaam stijgt naar ongeveer 17%; gas blijft ongeveer 0%. In diagram B daalt de vaste stof sneller, tot ongeveer 47% na 4 uur, terwijl olie stijgt tot ongeveer 53%; gas blijft laag. In diagram C daalt de vaste stof zeer snel (van 100% naar bijna 0% al na 0,5 uur), terwijl olie in dezelfde tijd snel stijgt naar ongeveer 90% en vervolgens weer daalt naar ongeveer 76% na 4 uur; gas stijgt geleidelijk naar ongeveer 22% na 4 uur.$$, 'inline'),
  ('8253a264-f8bf-4c67-8fe7-d6f1bb90402e', 'a1ceb518-4f23-4a70-9400-515989abae3b', $$conclusie uit diagram C — olie ontleedt bij 450 °C$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-plastic-wordt-olie-context6.png$$,
   $$Uit de resultaten in diagram C leidden de onderzoekers af dat bij 450 °C en een langere reactietijd een deel van de gevormde olie ontleedt.$$, 'inline'),
  ('cbd5055d-f8e0-45a0-ab16-2a078f95a5e2', 'a1ceb518-4f23-4a70-9400-515989abae3b', $$hexaan als bestanddeel van de olie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-plastic-wordt-olie-context7.png$$,
   $$Een bestanddeel van de ontstane olie is hexaan. Hexaan kan ontleden tot etheen en ethaan.$$, 'inline'),
  ('27e86adb-b681-44b0-aa0e-28acdf045721', '4aa1ed9f-a47e-44c6-8835-9bfb3979fc29', $$tekstfragment — flowbatterij op basis van natriumpolysulfide$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-ademende-flowbatterij-context1.png$$,
   $$Steeds meer elektrische energie wordt duurzaam opgewekt, bijvoorbeeld met behulp van zonnecellen. Hierdoor stijgt de vraag naar betaalbare opslag van energie. Een Amerikaans onderzoeksteam onder leiding van professor Chiang heeft daarom een ‘flowbatterij’ ontwikkeld op basis van goedkope stoffen zoals natriumpolysulfide (Na₂S₄).$$, 'inline'),
  ('eef74208-1e24-4459-a71d-2e6c92258ffd', '4aa1ed9f-a47e-44c6-8835-9bfb3979fc29', $$figuur 1 — schema van de flowbatterij$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-ademende-flowbatterij-context2.png$$,
   $$In figuur 1 is de flowbatterij schematisch weergegeven.
figuur 1: twee halfcellen (halfcel A en halfcel B), elk verbonden met een voorraadvat (voorraadvat A en voorraadvat B) via een pomp die de oplossing rondpompt. Halfcel A bevat elektrode A en is via een zuurstofdoorlatend membraan verbonden met de omgeving (H₂O, O₂ en H⁺ bij elektrode A). Halfcel B bevat elektrode B, met de deeltjes S₄²⁻ en S₂²⁻. Halfcel A en halfcel B zijn van elkaar gescheiden door een Na⁺-doorlatend membraan, waardoorheen Na⁺-ionen kunnen bewegen.$$, 'inline'),
  ('bbf14bc7-21d5-4d13-ba3e-bf5d3b996e27', '4aa1ed9f-a47e-44c6-8835-9bfb3979fc29', $$beginsituatie van halfcel A en halfcel B$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-ademende-flowbatterij-context3.png$$,
   $$De twee halfcellen A en B zijn ieder verbonden met een voorraadvat en zijn van elkaar gescheiden door een membraan dat Na⁺-ionen doorlaat. Tijdens het gebruik van de flowbatterij worden de oplossingen uit de voorraadvaten langs de elektroden gepompt (de ‘flow’). De elektroden reageren zelf niet mee. Wanneer de batterij nog niet is opgeladen, bevatten halfcel A en het daarop aangesloten voorraadvat A een oplossing van natriumsulfaat en zwavelzuur. Halfcel B en het daarop aangesloten voorraadvat B bevatten in niet opgeladen toestand een natriumpolysulfide-oplossing.$$, 'inline'),
  ('5f68df82-1855-4719-8696-9375e1a67552', '4aa1ed9f-a47e-44c6-8835-9bfb3979fc29', $$pH van halfcel B wordt verhoogd met natronloog$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-ademende-flowbatterij-context4.png$$,
   $$Om nevenreacties te voorkomen, wordt de pH in halfcel B verhoogd. Hiervoor is 3,0 M natriumhydroxide-oplossing gebruikt.$$, 'inline'),
  ('f5fcc3f9-1605-4588-bbb7-52422dfaa6d0', '4aa1ed9f-a47e-44c6-8835-9bfb3979fc29', $$halfreactie 1 en 2 tijdens het opladen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-ademende-flowbatterij-context5.png$$,
   $$Tijdens het opladen treden de volgende halfreacties op:
elektrode A: 2 H₂O → O₂ + 4 H⁺ + 4 e⁻ (halfreactie 1)
elektrode B: S₄²⁻ + 2 e⁻ → 2 S₂²⁻ (halfreactie 2)$$, 'inline'),
  ('285bc860-f014-4c76-a7be-3094f64fd243', '4aa1ed9f-a47e-44c6-8835-9bfb3979fc29', $$Chiang: de batterij ademt zuurstof in en uit$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-ademende-flowbatterij-context6.png$$,
   $$Chiang stelt dat deze batterij als het ware zuurstof in- en uitademt.$$, 'inline'),
  ('d0f44b56-ddf7-4d6f-8783-1dfb740e7cd7', '4aa1ed9f-a47e-44c6-8835-9bfb3979fc29', $$figuur 2 — PAN als grondstof voor het membraan$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-ademende-flowbatterij-context7.png$$,
   $$Een van de halfcellen van de flowbatterij bevat een membraan waardoor zuurstof kan passeren. Dit membraan bestaat onder andere uit een poreuze koolstoflaag die is gemaakt door het polymeer PAN te verkolen. In figuur 2 is de structuurformule van een gedeelte uit het midden van een PAN-molecuul weergegeven. De bindingsstreepjes tussen het C-atoom en het N-atoom zijn niet weergegeven.
figuur 2: structuurformule van een gedeelte van PAN: een keten van herhalende -CH₂-CH(CN)- eenheden (drie CH₂-groepen en drie CH-groepen met telkens een CN-zijgroep, zonder bindingsstreepje tussen C en N getekend).$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('bf07aa82-9fea-4797-9c11-866f991a40cb', 'd57a9644-791a-481e-93c1-c89c31944a87', 1,
   '[{"domain": "Rekenen en analyse", "subdomain": "Chemische vakmethodes"}]'::jsonb,
   '["scheidingsmethode", "filtreren", "rioolwater", "cellulosevezels", "stofeigenschap"]'::jsonb,
   $$Benoemen van de scheidingsmethode en het onderliggende stofeigenschapverschil om cellulosevezels uit rioolwater te verwijderen.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-toiletpapier-wordt-bio-ethanol-vraag1.png$$, $$Voer de volgende opdrachten uit:
– Geef de naam van de scheidingsmethode die kan worden toegepast om de cellulosevezels te verwijderen uit het rioolwater.
– Geef aan op welk verschil in eigenschap deze methode berust.$$, array['5d65ac84-5c9e-4768-9de9-67bde8f724c3']::uuid[]),
  ('9dcf198d-f68c-4f73-8371-4ffe19116288', 'd57a9644-791a-481e-93c1-c89c31944a87', 2,
   '[{"domain": "Materie", "subdomain": "Bindingen en eigenschappen"}]'::jsonb,
   '["waterstofbrug", "cellulose", "OH-groep", "intermoleculaire binding", "structuurformule"]'::jsonb,
   $$Tekenen van waterstofbruggen tussen twee cellulosemoleculen op basis van de structuurformule.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-toiletpapier-wordt-bio-ethanol-vraag2.png$$, $$Teken op de uitwerkbijlage twee waterstofbruggen die de twee cellulosemoleculen met elkaar verbinden.
Geef de waterstofbruggen weer met stippellijntjes (• • •).$$, array['6b613c66-6bc1-412d-a6f3-6cb4f0c7b349', 'fd2d9ae6-3239-42ba-9c15-940694ca15ef']::uuid[]),
  ('b033c8e6-d2e5-4820-9ce4-0bf7e4442ae8', 'd57a9644-791a-481e-93c1-c89c31944a87', 3,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["reactievergelijking", "reacties optellen", "coëfficiënten", "elementbalans", "vereenvoudigen"]'::jsonb,
   $$Optellen en vereenvoudigen van twee reactievergelijkingen tot de totale omzetting van syngas naar ethanol en water.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-toiletpapier-wordt-bio-ethanol-vraag3.png$$, $$Voer de volgende opdrachten uit:
– Tel beide reacties in de juiste verhouding bij elkaar op.
– Laat zien dat in de totale reactie uitsluitend ethanol en water ontstaan en vereenvoudig je vergelijking.$$, array['64532840-a510-401b-a213-b064d1f96f33']::uuid[]),
  ('6e4a34e5-618f-4a91-aa68-5bc38565ab3a', 'd57a9644-791a-481e-93c1-c89c31944a87', 4,
   '[{"domain": "Technologie en duurzaamheid", "subdomain": "Industriële processen en groene chemie"}]'::jsonb,
   '["atoomeconomie", "molaire massa", "rendement", "groene chemie"]'::jsonb,
   $$Berekenen van de atoomeconomie van de ethanolproductie uit cellotriose volgens reactie 3.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-toiletpapier-wordt-bio-ethanol-vraag4.png$$, $$Bereken de atoomeconomie voor de productie van ethanol volgens reactie 3.$$, array['22d39b29-535c-4602-93c3-170d38f528e2']::uuid[]),
  ('4a4aae3b-5ae6-4032-8a4c-4879715f892c', 'd57a9644-791a-481e-93c1-c89c31944a87', 5,
   '[{"domain": "Technologie en duurzaamheid", "subdomain": "Industriële processen en groene chemie"}]'::jsonb,
   '["groene chemie", "uitgangspunten", "procesvergelijking", "duurzaamheid", "biomassa"]'::jsonb,
   $$Beoordelen welk uitgangspunt van de groene chemie in het voordeel van het enzymatische proces (proces B) uitvalt ten opzichte van proces A.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-toiletpapier-wordt-bio-ethanol-vraag5.png$$, $$Geef een uitgangspunt van de groene chemie dat in het voordeel uitvalt van proces B ten opzichte van proces A. Licht je antwoord toe.
– Kies uit de uitgangspunten: 6, 8, 9 en 12.
– Gebruik Binas-tabel 97F of ScienceData-tabel 38.6.$$, array['493fd42c-3cc9-4e2f-8801-9ccebc445aa1']::uuid[]),
  ('14f93ff7-7143-42b0-af8b-3b465357f37f', '0ddeb54a-e790-489e-8ea0-4b301e27647f', 6,
   '[{"domain": "Technologie en duurzaamheid", "subdomain": "Energieomzettingen"}]'::jsonb,
   '["broeikaseffect", "methaan", "koolstofdioxide-equivalent", "klimaateffect"]'::jsonb,
   $$Benoemen van het versterkte broeikaseffect als gevolg van methaanuitstoot door koeien.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-koeien-boeren-methaan-op-vraag6.png$$, $$Geef de naam van dit ongewenste effect.$$, array['3d08ba4e-1571-4c33-9283-a4781be9b597']::uuid[]),
  ('5950d595-4218-4480-9056-37f4a02922ea', '0ddeb54a-e790-489e-8ea0-4b301e27647f', 7,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}, {"domain": "Reacties", "subdomain": "Classificatie van reacties"}]'::jsonb,
   '["hydrolyse", "cellulose", "disacharide", "structuurformule", "polysacharide"]'::jsonb,
   $$Voltooien van de reactievergelijking voor de hydrolyse van cellulose tot een disacharide, in structuurformules.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-koeien-boeren-methaan-op-vraag7.png$$, $$Maak op de uitwerkbijlage de reactievergelijking compleet van de hydrolyse van cellulose.
– Laat hierbij één disacharidemolecuul afsplitsen.
– Gebruik structuurformules.$$, array['56f30129-eebc-4dfc-b2d1-f83a97e63f43', '9cacc8df-6a8f-431e-8f20-140b96c0fbc2']::uuid[]),
  ('13e9e9a8-54f7-4b43-b58d-090b0b271883', '0ddeb54a-e790-489e-8ea0-4b301e27647f', 8,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["reactievergelijking", "glucose", "azijnzuur", "koolstofdioxide", "fermentatie", "molecuulformule"]'::jsonb,
   $$Opstellen van de gebalanceerde reactievergelijking voor de omzetting van glucose tot azijnzuur, koolstofdioxide en waterstof.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-koeien-boeren-methaan-op-vraag8.png$$, $$Geef de vergelijking van deze reactie in molecuulformules. Neem aan dat per molecuul glucose twee moleculen azijnzuur ontstaan.$$, array['4f748744-fe64-4b71-bad1-7bc8c930a086']::uuid[]),
  ('6fe55e0e-9fdc-4522-ad4a-e0bb4c5048c7', '0ddeb54a-e790-489e-8ea0-4b301e27647f', 9,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["molverhouding", "molair volume", "significante cijfers", "stoichiometrie", "reactievergelijking"]'::jsonb,
   $$Berekenen van het volume methaan dat gemiddeld per dag in een koe ontstaat, via de reactievergelijking en het gegeven molair volume.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-i-koeien-boeren-methaan-op-vraag9.png$$, $$Bereken het volume in liters methaan dat gemiddeld per dag in een koe ontstaat. Geef de uitkomst in het juiste aantal significante cijfers.
Gebruik hierbij de volgende gegevens:
– In een koe wordt gemiddeld per dag 165 gram H₂ omgezet tot CH₄ volgens reactie 1.
